// u=1 on Sutherland's optimized X_1(95) model.
// https://math.mit.edu/~drew/X1/X1opt95new.txt
Q<t>:=PolynomialRing(Rationals());
g:=t^54 - 24*t^53 + 267*t^52 - 1786*t^51 + 7750*t^50 - 21116*t^49 + 
    23869*t^48 + 79929*t^47 - 524430*t^46 + 1571350*t^45 - 2948862*t^44 + 
    2991992*t^43 + 1015830*t^42 - 9479919*t^41 + 17310953*t^40 - 20650537*t^39 +
    31800045*t^38 - 71430136*t^37 + 121027405*t^36 - 105138267*t^35 - 
    13294312*t^34 + 129923902*t^33 - 112741294*t^32 + 46748707*t^31 - 
    176522233*t^30 + 491352051*t^29 - 601246052*t^28 + 266742957*t^27 + 
    165153572*t^26 - 206582254*t^25 - 57847921*t^24 + 139338010*t^23 + 
    79403265*t^22 - 233080800*t^21 + 122690042*t^20 + 17434282*t^19 + 
    26866773*t^18 - 145320750*t^17 + 165213580*t^16 - 108479790*t^15 + 
    75563396*t^14 - 76395966*t^13 + 66547089*t^12 - 37386341*t^11 + 
    11395148*t^10 - 299520*t^9 - 1193526*t^8 + 422371*t^7 - 18984*t^6 - 
    27542*t^5 + 8885*t^4 - 1066*t^3 - 7*t^2 + 14*t - 1;
assert Degree(g) eq 54 and IsIrreducible(g);
K<v>:=NumberField(g);
x:=1/v;
// Substitute G=-u=-1 into the birational reconstruction of y.
y:=((-18750)*x^0 + (596875)*x^1 + (-9015625)*x^2 + (85190625)*x^3 + (-559025000)*x^4 + (2666918750)*x^5 + (-9329693750)*x^6 + (22893903125)*x^7 + (-30745428125)*x^8 + (-32492987500)*x^9 + (343486140625)*x^10 + (-1251020762500)*x^11 + (3383736968750)*x^12 + (-8052035125000)*x^13 + (18262322065625)*x^14 + (-39748063421875)*x^15 + (78786786462500)*x^16 + (-130937170700000)*x^17 + (158335943621875)*x^18 + (-68224810621875)*x^19 + (-278812308978125)*x^20 + (1017148505315625)*x^21 + (-2221592689431250)*x^22 + (3911961124975000)*x^23 + (-6072527389221875)*x^24 + (8503609329500000)*x^25 + (-10458705654718750)*x^26 + (10473169921084375)*x^27 + (-6938551824556250)*x^28 + (-751230232262500)*x^29 + (11562116363821875)*x^30 + (-23421074758878125)*x^31 + (34317004801581250)*x^32 + (-42643011883984375)*x^33 + (46848255554912500)*x^34 + (-45576248307362500)*x^35 + (38543541698231250)*x^36 + (-27043135994900000)*x^37 + (13433754931675000)*x^38 + (-295918380828125)*x^39 + (-10189947610353125)*x^40 + (16937605782909375)*x^41 + (-20527749068518750)*x^42 + (22648483223381250)*x^43 + (-24508307092362500)*x^44 + (25993556208675000)*x^45 + (-26488432354856250)*x^46 + (25948335001403125)*x^47 + (-24742753723334375)*x^48 + (22899647907646875)*x^49 + (-20119694440615625)*x^50 + (16432101779196875)*x^51 + (-12403724540103125)*x^52 + (8688767850646875)*x^53 + (-5631072262575000)*x^54 + (3301144793606250)*x^55 + (-1679621460793750)*x^56 + (700651967612500)*x^57 + (-219005801675000)*x^58 + (40041142431250)*x^59 + (2721270612500)*x^60 + (-4636516150000)*x^61 + (1427275925000)*x^62 + (-75959515625)*x^63 + (-106873918750)*x^64 + (49190950000)*x^65 + (-11731062500)*x^66 + (1662606250)*x^67 + (-107918750)*x^68 + (-6862500)*x^69 + (2150000)*x^70 + (-187500)*x^71 + (6250)*x^72)/((x-1)*((68750)*x^0 + (-2190625)*x^1 + (33384375)*x^2 + (-321262500)*x^3 + (2171796875)*x^4 + (-10829262500)*x^5 + (40339106250)*x^6 + (-108278203125)*x^7 + (171091018750)*x^8 + (99919159375)*x^9 + (-1754797037500)*x^10 + (6887213965625)*x^11 + (-17783236693750)*x^12 + (33735832796875)*x^13 + (-46745289159375)*x^14 + (41219301196875)*x^15 + (-270019690625)*x^16 + (-93298507606250)*x^17 + (279293862109375)*x^18 + (-644830306178125)*x^19 + (1274823002940625)*x^20 + (-2103896020393750)*x^21 + (2832448220300000)*x^22 + (-3113057917359375)*x^23 + (2853698521809375)*x^24 + (-2131929306668750)*x^25 + (650564247096875)*x^26 + (2399038611587500)*x^27 + (-7351202900940625)*x^28 + (12934335981828125)*x^29 + (-16860058662900000)*x^30 + (18000226373525000)*x^31 + (-17420315252990625)*x^32 + (16602169168971875)*x^33 + (-15175329821825000)*x^34 + (11512764865537500)*x^35 + (-5503453891403125)*x^36 + (-526445194390625)*x^37 + (4220165030787500)*x^38 + (-5651493974803125)*x^39 + (6638974562900000)*x^40 + (-8215332899487500)*x^41 + (9735283467025000)*x^42 + (-10296518783800000)*x^43 + (10032822721909375)*x^44 + (-9657020883037500)*x^45 + (9370298999309375)*x^46 + (-8765405636303125)*x^47 + (7562348602709375)*x^48 + (-5983020266053125)*x^49 + (4426563606678125)*x^50 + (-3092102067100000)*x^51 + (1989515316356250)*x^52 + (-1119825256828125)*x^53 + (518316226875000)*x^54 + (-182089572303125)*x^55 + (40576747131250)*x^56 + (-816188406250)*x^57 + (-3393628300000)*x^58 + (1314648650000)*x^59 + (-152695359375)*x^60 + (-66426450000)*x^61 + (38894862500)*x^62 + (-10184518750)*x^63 + (1551593750)*x^64 + (-112987500)*x^65 + (-4887500)*x^66 + (1968750)*x^67 + (-181250)*x^68 + (6250)*x^69)*x);
r:=(x^2*y-x*y+y-1)/(x^2*y-x);
s:=(x*y-y+1)/(x*y);
E:=EllipticCurve([s-r*s+1,r*s-r^2*s,r*s-r^2*s,0,0]);
P:=E![0,0];
assert Discriminant(E) ne 0;
assert 95*P eq E!0 and 19*P ne E!0 and 5*P ne E!0;
// The Tate normal form for a marked point of order greater than three is unique.
// Thus r (the quotient of b and c in that normal form) belongs to its field of moduli.
assert Degree(MinimalPolynomial(r)) eq 54;
assert Degree(MinimalPolynomial(jInvariant(E))) eq 27;
print "VERIFIED",Degree(K),95;
quit;
